<!doctype html>
<!-- Solmarina — round 4 authorship pass (recording 14): file re-emitted under a live recording. -->
<!-- Round 4 pass 2: second recorded touch; game logic untouched. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Solmarina</title>
<link rel="icon" href="data:,">
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #0a0e14; }
  #game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
  #loading { position: fixed; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #e8dcc8; font-family: system-ui, sans-serif; z-index: 100; background: linear-gradient(180deg, #0a0e14 0%, #1a2a3a 100%); }
  #loading .spinner { width: 48px; height: 48px; border: 3px solid #2a3a4a; border-top-color: #e8c56a; border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 16px; }
  @keyframes spin { to { transform: rotate(360deg); } }
  #loading .progress { width: 240px; height: 4px; background: #2a3a4a; border-radius: 2px; overflow: hidden; }
  #loading .progress-bar { width: 0%; height: 100%; background: linear-gradient(90deg, #e8c56a, #d4a84a); transition: width 0.3s; }
  #status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  #loadError { display: none; max-width: 520px; margin-top: 20px; padding: 12px 16px; background: #3a0d0d; border: 1px solid #a33; border-radius: 6px; color: #ffb3b3; font-size: 13px; line-height: 1.5; text-align: left; white-space: pre-wrap; word-break: break-word; }
</style>
</head>
<body>
<noscript><p style="color:#e8dcc8;font-family:system-ui;padding:40px;text-align:center;">Solmarina needs JavaScript enabled to run.</p></noscript>
<canvas id="game" tabindex="0" aria-label="Solmarina: open-world crime game set in a sun-soaked coastal city"></canvas>
<p id="status" role="status" aria-live="polite"></p>
<div id="loading" role="alert" aria-busy="true"><div class="spinner"></div><div class="progress"><div class="progress-bar" id="progressBar"></div></div><span id="loadingText">Loading Solmarina...</span><div id="loadError" role="alert"></div></div>
<script>
  // Shown instead of a stuck spinner when the game cannot start: a failed
  // module load or a missing WebGL context used to leave the loading screen
  // spinning forever with no message. Also used by main.js to report init
  // progress (window.__solmarinaProgress) and fatal init errors.
  (function () {
    var box = document.getElementById('loadError');
    function showError(msg) {
      if (!box) return;
      box.style.display = 'block';
      box.textContent = msg;
      var spin = document.querySelector('#loading .spinner');
      if (spin) spin.style.display = 'none';
    }
    window.__solmarinaLoadError = showError;
    window.__solmarinaProgress = function (pct, text) {
      var bar = document.getElementById('progressBar');
      if (bar) bar.style.width = Math.max(0, Math.min(100, pct)) + '%';
      var label = document.getElementById('loadingText');
      if (label && text) label.textContent = text;
    };
    window.addEventListener('error', function (e) {
      showError('Failed to load Solmarina: ' + (e.message || 'unknown error') + '\nCheck your connection and reload the page.');
    });
    window.addEventListener('unhandledrejection', function (e) {
      showError('Solmarina hit an error while loading: ' + (e.reason && e.reason.message ? e.reason.message : e.reason));
    });
    // WebGL pre-check: the renderer needs it, so fail fast with a message.
    try {
      var test = document.createElement('canvas');
      if (!test.getContext('webgl2') && !test.getContext('webgl')) {
        showError('WebGL is not available in this browser, so Solmarina cannot start.\nTry a recent Chrome, Edge or Firefox with hardware acceleration enabled.');
      }
    } catch (err) {
      showError('WebGL check failed: ' + err.message);
    }
  })();
</script>
<script type="importmap">
{
  "imports": {
    "three": "./vendor/three.module.min.js"
  }
}
</script>
<script type="module" src="./src/main.js"></script>
</body>
</html>
