  }

  // Get nearest street position for vehicle spawning
  getNearestStreetPosition(x, z, radius = 50) {
    let best = null;
    let bestDist = radius * radius;

    for (const node of this.trafficNodes) {
      if (node.type === 'street') {
        const dx = node.x - x;
        const dz = node.z - z;
        const distSq = dx * dx + dz * dz;
        if (distSq < bestDist) {
          bestDist = distSq;
          best = node;
        }
      }
    }
    return best;
  }

