  // Update animated elements
  update(delta, timeOfDay) {
    // Accumulate elapsed time for animations
    this.elapsed = (this.elapsed || 0) + delta;

    // Water animation
    if (this.water) {
      this.water.userData.time += delta;
      const t = this.water.userData.time;
      this.water.material.color.lerpColors(
        this.waterDayColor,
        this.waterNightColor,
        (Math.sin(t * 0.5) + 1) * 0.5 * 0.3
      );
    }

    // Day factor for time of day (0 = night, 1 = day)
    const dayFactor = (Math.sin(timeOfDay * Math.PI * 2) + 1) / 2;
    const angle = timeOfDay * Math.PI * 2;

    // Sky color based on time of day
    if (this.sky) {
      // Use setHex for reliable color interpolation
      const nightColor = new THREE.Color(CONFIG.PALETTE.SKY_NIGHT);
      const dayColor = new THREE.Color(CONFIG.PALETTE.SKY_DAY);
      const skyColor = new THREE.Color().lerpColors(nightColor, dayColor, dayFactor);
      // Sunset tint: when the sun is low (dayFactor mid-low, but not yet
      // night), warm the sky and fog toward the sunset palette so dusk
      // actually reads as dusk instead of a dim grey day.
      const sunsetAmount = clamp((0.5 - dayFactor) / 0.35, 0, 1) * clamp((dayFactor - 0.08) / 0.12, 0, 1);
      if (sunsetAmount > 0) {
        skyColor.lerp(new THREE.Color(CONFIG.PALETTE.SKY_SUNSET), sunsetAmount * 0.7);
      }
      this.sky.material.color.copy(skyColor);

      // Fog color
      const fogNight = new THREE.Color(CONFIG.PALETTE.FOG_NIGHT);
      const fogDay = new THREE.Color(CONFIG.PALETTE.FOG_DAY);
      this.scene.fog.color.lerpColors(fogNight, fogDay, dayFactor);
      if (sunsetAmount > 0) {
        this.scene.fog.color.lerp(new THREE.Color(CONFIG.PALETTE.FOG_SUNSET), sunsetAmount * 0.7);
      }
    }

    // Sun position
    if (this.sun) {
      this.sun.position.set(
        Math.cos(angle) * 400,
        Math.sin(angle) * 400 + 200,
        Math.sin(angle) * 300
      );

      // Sun color
      const sunNight = new THREE.Color(CONFIG.PALETTE.SKY_NIGHT);
      const sunDay = new THREE.Color(CONFIG.PALETTE.SUN_COLOR);
      this.sun.material.color.lerpColors(sunNight, sunDay, dayFactor);

      if (this.ambientLight) {
        this.ambientLight.intensity = 0.55 + 0.65 * dayFactor;
        this.ambientLight.color.setHSL(0.1, 0.3, 0.5 * dayFactor + 0.3);
        this.ambientLight.groundColor.setHSL(0.6, 0.2, 0.1 * dayFactor + 0.05);
      }
    }

    // Update sun light position to match sun, and scale its intensity with
    // the time of day (it used to be a flat 1.0, so noon looked like dusk
    // and shaded building faces went near-black under ACES tonemapping).
    if (this.sunLight) {
      this.sunLight.position.copy(this.sun.position);
      this.sunLight.intensity = 0.4 + 2.2 * dayFactor;
    }

    // Streetlight glow pulse
    for (const light of this.streetlights) {
      if (light.userData.glow) {
        const intensity = 0.3 + Math.sin(this.elapsed * 2 + light.position.x * 0.1) * 0.2;
        light.userData.glow.material.opacity = intensity;
      }
    }
  }

  // Raycast to ground
  raycastGround(x, z) {
    const raycaster = new THREE.Raycaster(
      new THREE.Vector3(x, 100, z),
      new THREE.Vector3(0, -1, 0),
      0, 200
    );
    const intersects = raycaster.intersectObject(this.ground, true);
    return intersects[0] ? intersects[0].point.y : 0;
  }

  // Check if position is on street
  isOnStreet(x, z, tolerance = 2) {
    for (const street of this.streets) {
      if (street.width) {
        const dx = x - street.x1;
        const dz = z - street.z1;
        const lenSq = (street.x2 - street.x1) ** 2 + (street.z2 - street.z1) ** 2;
        if (lenSq === 0) continue;
        const t = Math.max(0, Math.min(1, (dx * (street.x2 - street.x1) + dz * (street.z2 - street.z1)) / lenSq));
        const projX = street.x1 + t * (street.x2 - street.x1);
        const projZ = street.z1 + t * (street.z2 - street.z1);
        const dist = Math.sqrt((x - projX) ** 2 + (z - projZ) ** 2);
        if (dist < street.width / 2 + tolerance) return true;
      }
    }
    return false;
  }

  // Get street direction at position
  getStreetDirection(x, z) {
    for (const street of this.streets) {
      if (street.width) {
        const dx = x - street.x1;
        const dz = z - street.z1;
        const lenSq = (street.x2 - street.x1) ** 2 + (street.z2 - street.z1) ** 2;
        if (lenSq === 0) continue;
        const t = Math.max(0, Math.min(1, (dx * (street.x2 - street.x1) + dz * (street.z2 - street.z1)) / lenSq));
        const projX = street.x1 + t * (street.x2 - street.x1);
        const projZ = street.z1 + t * (street.z2 - street.z1);
        const dist = Math.sqrt((x - projX) ** 2 + (z - projZ) ** 2);
        if (dist < street.width / 2 + 2) {
          return new THREE.Vector3(street.x2 - street.x1, 0, street.z2 - street.z1).normalize();
        }
      }
    }
    return null;
  }
